// Tanren postgres-prisma — the seed schema. Extend with project models.
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

model TanrenDemo {
  id        String   @id @default(cuid())
  createdAt DateTime @default(now())
  message   String
}

flatMap.prisma/seed.ts:
// Tanren prisma seed — a noop seed the project extends. Run via `pnpm prisma db seed`.
import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();

async function main() {
  await prisma.tanrenDemo.create({ data: { message: "tanren seed ran" } });
}

main()
  .then(async () => {
    await prisma.$disconnect();
  })
  .catch(async (e) => {
    console.error(e);
    await prisma.$disconnect();
    process.exit(1);
  });

